using System.Globalization;
using System.Reflection;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;
using System.Windows.Media.Imaging;
using GraficaCaixa;
using GraficaCaixa.Wpf;

static class Prompt7Tests
{
    static int count;
    static void Check(bool value,string name){if(!value)throw new Exception(name);Console.WriteLine("OK "+name);count++;}
    static void Reject(Action action,string name){try{action();}catch(InvalidOperationException){Check(true,name);return;}throw new Exception("Aceitou indevidamente: "+name);}
    static T Field<T>(object value,string name)=>(T)value.GetType().GetField(name,BindingFlags.Instance|BindingFlags.NonPublic|BindingFlags.Public)!.GetValue(value)!;
    static void Call(object value,string name)=>value.GetType().GetMethod(name,BindingFlags.Instance|BindingFlags.NonPublic)!.Invoke(value,[value,new RoutedEventArgs()]);
    static IEnumerable<T> All<T>(DependencyObject root) where T:DependencyObject {if(root is T match)yield return match;foreach(var child in LogicalTreeHelper.GetChildren(root).OfType<DependencyObject>())foreach(var x in All<T>(child))yield return x;}
    static void Render(Window window,string path){var content=(FrameworkElement)window.Content;content.Measure(new Size(window.Width-32,window.Height-58));content.Arrange(new Rect(0,0,window.Width-32,window.Height-58));content.UpdateLayout();var image=new RenderTargetBitmap((int)window.Width,(int)window.Height,96,96,PixelFormats.Pbgra32);var visual=new DrawingVisual();using(var dc=visual.RenderOpen()){dc.DrawRectangle(Brushes.White,null,new Rect(0,0,window.Width,window.Height));dc.DrawRectangle(new VisualBrush(content),null,new Rect(0,0,content.ActualWidth,content.ActualHeight));}image.Render(visual);var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(image));using var stream=File.Create(path);encoder.Save(stream);}
    public static void Run()
    {
        CultureInfo.CurrentCulture=CultureInfo.GetCultureInfo("pt-BR");
        var folder=Path.GetFullPath(Path.Combine("work","prompt7-qa",Guid.NewGuid().ToString("N")));Directory.CreateDirectory(folder);
        var app=new App();app.InitializeComponent();app.ShutdownMode=ShutdownMode.OnExplicitShutdown;
        var admin=OperationContext.Administrator("Teste Prompt7");var store=new DataStore(Path.Combine(folder,"db"));store.EnsureInitialized();store.Load();
        var q=new TextBox{Text="10"};var unit=new TextBox{Text="5,00"};var sub=new TextBox();Check(ItemPricing.Update(q,unit,sub,false,out var valid)==50&&valid,"Quantidade × unitário");sub.Text="45,00";Check(ItemPricing.Update(q,unit,sub,true,out valid)==45&&unit.Text=="4,50","Subtotal manual recalcula unitário");q.Text="3";Check(ItemPricing.Update(q,unit,sub,true,out valid)==45&&decimal.Parse(unit.Text)==15,"Quantidade mantém subtotal fechado");sub.Text="10,00";Check(ItemPricing.Update(q,unit,sub,true,out valid)==10,"Divisão fracionária preserva subtotal");q.Text="0";ItemPricing.Update(q,unit,sub,true,out valid);Check(!valid,"Quantidade inválida rejeitada");
        var sale=new SaleWindow(store:store);Check(All<Button>(sale).Any(x=>x.Content?.ToString()?.TrimStart('+','＋','▧',' ')?.Equals("Novo produto",StringComparison.OrdinalIgnoreCase)==true),"Atalho usa formulário existente");Check(All<FinancialSummary>(sale).Count()==1,"Resumo compartilhado no lançamento");var pay=Field<PaymentEditor>(sale,"payments");pay.Add("Cartão de crédito 3x",20);var combos=All<ComboBox>(pay).ToList();Check(combos.Where(x=>x.Items.Count==12).All(x=>x.Visibility!=Visibility.Visible),"Parcelas ocultas no lançamento");var amounts=All<TextBox>(pay).ToList();amounts[0].Text="10,00";Check(pay.Read(30).Last().PaymentType=="Cartão de crédito 1x","Crédito do lançamento sempre 1x");Check(pay.Amount==30,"Pagamento misto");Reject(()=>pay.Read(29),"Pagamento acima do saldo bloqueado");var itemGrid=Field<StackPanel>(sale,"itemPanel").Children.OfType<Grid>().First();var itemFields=itemGrid.Children.OfType<TextBox>().ToList();itemFields[0].Text="10";itemFields[1].Text="Produto manual";itemFields[2].Text="5,00";itemFields[3].Text="45,00";Check(decimal.Parse(itemFields[2].Text)==4.5m,"Subtotal manual na tela de lançamento");typeof(SaleWindow).GetMethod("AddItem",BindingFlags.Instance|BindingFlags.NonPublic)!.Invoke(sale,[null]);Check(Field<StackPanel>(sale,"itemPanel").Children.Count==2,"Vários itens no lançamento");Render(sale,Path.Combine(folder,"lancamento.png"));
        var orderWindow=new ScheduledOrderDialog(store);Check(All<FinancialSummary>(orderWindow).Count()==1,"Resumo compartilhado no pedido");Field<ComboBox>(orderWindow,"PricingModeBox").SelectedIndex=0;Field<TextBox>(orderWindow,"TotalBox").Text="100,00";Field<TextBox>(orderWindow,"DiscountBox").Text="5";Call(orderWindow,"ApplyDiscount_Click");Check(Field<decimal>(orderWindow,"appliedDiscount")==5,"Desconto percentual na interface");Field<ComboBox>(orderWindow,"DiscountMode").SelectedIndex=1;Call(orderWindow,"ApplyDiscount_Click");Check(Field<decimal?>(orderWindow,"appliedFixed")==5&&Field<decimal>(orderWindow,"appliedDiscount")==0,"Desconto em reais exclusivo");Render(orderWindow,Path.Combine(folder,"pedido.png"));
        var data=new AppData{Sessions=[new CashSession{OpeningAmount=0,OpenedBy=admin.UserName}]};ScheduledOrder Draft()=>new(){CustomerName="Cliente de teste",Description="Impressão",OriginalTotal=100,OrderTotal=100,Items=[new OrderItem{Quantity=10,Product="Impressão",UnitPrice=10}],UseItemPrices=true};
        var percent=Draft();percent.DiscountPercent=5;OrderOperations.Save(data,percent,admin);Check(data.ScheduledOrders.Single().OrderTotal==95,"5% de R$ 100 = R$ 95");var fixedOrder=Draft();fixedOrder.FixedDiscount=5;OrderOperations.Save(data,fixedOrder,admin);var saved=data.ScheduledOrders.Single(x=>x.Id==fixedOrder.Id);Check(saved.OrderTotal==95,"R$ 5 de R$ 100 = R$ 95");var bad=Draft();bad.FixedDiscount=5;bad.DiscountPercent=5;Reject(()=>OrderOperations.Save(data,bad,admin),"Duas modalidades simultâneas bloqueadas");bad=Draft();bad.FixedDiscount=101;Reject(()=>OrderOperations.Save(data,bad,admin),"Desconto maior que total bloqueado");
        OrderOperations.AddPayment(data,saved,20,"PIX",DateTime.Now,"Sinal",Guid.NewGuid(),admin);OrderOperations.AddPayment(data,saved,30,"Cartão de crédito 3x",DateTime.Now,"Parcela",Guid.NewGuid(),admin);Check(saved.PaidAmount==50&&saved.RemainingAmount==45,"Recebimento parcial e saldo preservados");Check(saved.EstimatedFees==2.04m,"Taxa mista por modalidade");
        store.Update(d=>{d.ScheduledOrders=data.ScheduledOrders;d.Sessions=data.Sessions;d.AuditTrail=data.AuditTrail;d.PaymentRates=new(){["PIX"]=1.25m,["Cartão de crédito 1x"]=4.25m};return 0;});var restored=store.Load();Check(restored.ScheduledOrders.Single(x=>x.Id==saved.Id).FixedDiscount==5,"Desconto em reais persistido sem alteração de esquema");Check(PaymentPolicy.Rate("PIX")==1.25m&&PaymentPolicy.Rate("Cartão de crédito 1x")==4.25m,"Taxas configuradas persistidas e usadas");Check(PaymentPolicy.Rate("Cartão de débito")==1.59m,"Taxas não editadas preservadas");Check(restored.ScheduledOrders.Single(x=>x.Id==saved.Id).EstimatedFees==2.04m,"Taxas históricas preservadas");Check(new Sale{PaymentType="Cartão de crédito 1x",TotalValue=100}.EstimatedFee==3.99m,"Histórico sem snapshot mantém taxa original");
        Reject(()=>store.Update(d=>{d.PaymentRates["PIX"]=-1;return 0;}),"Taxa inválida não salva");Check(store.Load().PaymentRates["PIX"]==1.25m,"Valor anterior mantido após rejeição");Reject(()=>DocumentPaths.Validate(Path.Combine(folder,"ausente")),"Caminho inexistente rejeitado");Check(new SearchSaleRow(new CashSession(),new Sale{TotalValue=-150}).TotalForeground=="#C62828","Negativo em vermelho");Check(new SearchSaleRow(new CashSession(),new Sale{TotalValue=150}).TotalForeground!="#C62828","Positivo normal");
        var product=new ProductEditor(null);Render(product,Path.Combine(folder,"produto.png"));Check(All<TextBlock>(product).Any(x=>x.Text.Equals("Incluir foto",StringComparison.OrdinalIgnoreCase)),"Botão de incluir foto disponível");var settings=new SettingsWindow(store);Check(All<Image>(settings).Any(x=>x.Source!=null),"Prévia do logotipo atual preservada");Render(settings,Path.Combine(folder,"configuracoes.png"));Check(All<TabItem>(settings).Count()==5,"Configurações com cinco áreas");
        ReportWriter.OutputFolder=folder;var sheet=ReportWriter.WriteOrderSheet([saved],Path.Combine(folder,"pedido-pago.pdf"));ReportWriter.WriteOrderSheet([percent],Path.Combine(folder,"pedido-sem-pagamento.pdf"));ReportWriter.WriteReceipt(saved,Path.Combine(folder,"recibo.pdf"));
        for(int i=0;i<12;i++)saved.Payments.Add(new OrderPayment{SaleId=Guid.NewGuid(),PaymentType="PIX",Amount=1,PaidAt=DateTime.Now});ReportWriter.WriteOrderSheet([saved],Path.Combine(folder,"pedido-muitos-pagamentos.pdf"));
        Console.WriteLine($"PASS {count} testes direcionados. QA: {folder}");app.Shutdown();
    }
}

